<?php
require_once __DIR__.'/auth.php'; require_login(); $activeAdmin='comercial';
$file=dirname(__DIR__).'/data/anuncios_pedidos.json'; function rj($f){ if(!file_exists($f)) return []; $d=json_decode(file_get_contents($f),true); return is_array($d)?$d:[];} function sj($f,$d){ file_put_contents($f,json_encode(array_values($d),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);} $orders=rj($file);
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=$_POST['id']??''; $action=$_POST['action']??''; foreach($orders as &$o){ if(($o['id']??'')===$id){ if($action==='approve') $o['status']='aprovado'; if($action==='publish') $o['status']='publicado'; if($action==='paid') $o['status']='pagamento confirmado'; }} unset($o); if($action==='delete') $orders=array_values(array_filter($orders,fn($o)=>($o['id']??'')!==$id)); sj($file,$orders); header('Location: area-comercial.php?ok=1'); exit; }
function h($v){return htmlspecialchars((string)$v);} ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Área Comercial</title><link rel="stylesheet" href="admin.css?v=41"></head><body><div class="admin"><?php include __DIR__.'/_menu.php'; ?><main class="main"><div class="top"><div><span class="eyebrow">Anunciantes</span><h1>Área Comercial</h1></div><a class="btn secondary" target="_blank" href="../anuncie.php">Ver planos</a></div><div class="box"><h2>Pedidos de anúncios e banners</h2><?php if(!$orders): ?><p>Nenhuma solicitação recebida.</p><?php endif; ?><?php foreach(array_reverse($orders) as $o): ?><div class="box"><h2><?=h($o['company']??'Empresa')?></h2><p><b>Plano:</b> <?=h($o['plan']??'')?> • <b>Local:</b> <?=h($o['placement']??'')?> • <b>Status:</b> <?=h($o['status']??'recebido')?></p><p><b>Responsável:</b> <?=h($o['responsible']??'')?> • <b>WhatsApp:</b> <?=h($o['whatsapp']??'')?> • <b>E-mail:</b> <?=h($o['email']??'')?></p><p><?=h($o['message']??'')?></p><p><b>Arte:</b> <?=h($o['banner']??'Não enviada')?> • <b>Comprovante:</b> <?=h($o['receipt']??'Não enviado')?></p><form method="post" class="actions"><?=tvs_csrf_field()?><input type="hidden" name="id" value="<?=h($o['id']??'')?>"><button class="btn secondary" name="action" value="paid">Marcar pago</button><button class="btn" name="action" value="approve">Aprovar</button><button class="btn orange" name="action" value="publish">Publicar</button><button class="btn danger" name="action" value="delete" onclick="return confirm('Excluir pedido?')">Excluir</button></form></div><?php endforeach; ?></div></main></div></body></html>
